/* ============================================================================
   MSG-01 · Panel de contenido de la lista de hilos.
   ============================================================================
   Mismas decisiones que ThreadList.module.css: donde el HTML aprobado usa
   `white`, se usa `--bw-warm-cream` (no hay token de blanco puro en F-003).
   Además, `--bw-input-placeholder` (#9BA4B0) se usa también para textos
   auxiliares en gris con ese mismo valor, porque es el único token que
   coincide con el #9BA4B0 del HTML aprobado.
   ========================================================================== */

.page {
  flex: 1;
  overflow-y: auto;
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.pageTitle {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin-bottom: 3px;
}

.pageSub {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin-bottom: 16px;
  max-width: 560px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchWrap > i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: 13px;
  color: var(--bw-deep-steel);
  outline: none;
  background: var(--bw-warm-cream);
  font-family: inherit;
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.btnPrimary {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-warm-cream);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  transition: opacity 0.12s;
}

.btnPrimary:hover:not(:disabled) {
  opacity: 0.88;
}

.btnPrimary:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.threadCount {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  margin-left: auto;
  white-space: nowrap;
}

.status {
  padding: 40px 18px;
  text-align: center;
  color: var(--bw-steel-mist);
  font-size: 13px;
}

.error {
  padding: 14px 18px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  font-size: 13px;
}

.empty {
  padding: 60px 24px;
  text-align: center;
  /* Borde discontinuo: se reutiliza el token del sistema de la mini-dropzone,
     el único token de borde discontinuo de F-003. */
  border: 1px dashed var(--bw-dropzone-border);
  border-radius: 8px;
  background: var(--bw-warm-cream);
  color: var(--bw-steel-mist);
  font-size: 14px;
  line-height: 1.6;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

.empty p {
  max-width: 420px;
  margin: 0;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
  flex-wrap: wrap;
}

.pageBtn {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition:
    border-color 0.12s,
    color 0.12s,
    background 0.12s;
}

.pageBtn:hover:not(:disabled):not(.pageActive) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  color: var(--bw-input-placeholder);
  cursor: default;
}

.pageActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

