/* ============================================================================
   MSG-01 · Lista de hilos — filas.
   ============================================================================
   El HTML aprobado pinta la tarjeta con `white`. La paleta F-003 no define un
   blanco puro, así que las superficies "blancas" usan `--bw-warm-cream`
   (#FAF8F4), el token más claro disponible. No es un color nuevo: es el más
   cercano que permite el vocabulario cerrado.
   ========================================================================== */

.list {
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--bw-surface-mist);
  /* El HTML aprobado usa #F8F9FB como línea entre filas; el único token con
     ese valor es --bw-surface-mist. */
  cursor: pointer;
  transition: background 0.1s;
}

.row:last-child {
  border-bottom: none;
}

.row:hover {
  background: var(--bw-row-hover-tint);
}

.row:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
  border-color: var(--bw-calibration-blue);
}

.top {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.org {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.countryBadge {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  flex-shrink: 0;
}

.tsRow {
  display: flex;
  align-items: center;
  gap: 6px;
  justify-content: flex-end;
}

.ts {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.bottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  font-size: 12px;
  color: var(--bw-text-secondary);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* ── Tonos de estado ───────────────────────────────────────────────────────
   Cada uno mapea el hex de la spec §3 al token de la familia de badges.
   El borde "info" del HTML aprobado usa rgba(37,99,235,.2); el token más
   cercano de F-003 es --bw-chip-active-border (rgba(37,99,235,.3)).
   El fondo "abierto" del HTML usa rgba(107,122,153,.1); el token de badge
   neutro más cercano es --bw-badge-neutral-bg (rgba(107,122,153,.08)).
   El texto "cerrado" del HTML usa #9BA4B0; el único token con ese valor es
   --bw-input-placeholder. El borde "cerrado" (rgba(107,122,153,.15)) coincide
   con --bw-badge-neutral-border-soft. */

.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

