import {
  previewLabel,
  relativeTime,
  stateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  onOpen: (id: string) => void;
}

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Pinta las filas en el orden exacto en que las recibe: el orden lo decide el
 * servidor (`fetchThreadPage` ordena por `last_item_at` descendente). Al abrir
 * una fila avisa con el ID del hilo, no con el objeto.
 */
export function ThreadList({ threads, now = new Date(), onOpen }: ThreadListProps) {
  return (
    <div className={styles.list}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        return (
          <div
            key={thread.id}
            role="button"
            tabIndex={0}
            className={styles.row}
            aria-label={`Abrir hilo con ${thread.counterpartyName}`}
            onClick={() => onOpen(thread.id)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onOpen(thread.id);
              }
            }}
          >
            <div className={styles.top}>
              <span className={styles.org}>{thread.counterpartyName}</span>
              <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
            </div>
            <div className={styles.tsRow}>
              <time className={styles.ts} dateTime={thread.lastItemAt}>
                {relativeTime(thread.lastItemAt, now)}
              </time>
            </div>
            <div className={styles.bottom}>
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.stateBadge} ${styles[tone]}`}>{thread.state}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}
